create table institutional_organizations (id uuid primary key default gen_random_uuid(), slug text not null unique, display_name text not null, environment text not null check (environment = 'TESTNET'), created_at timestamptz not null default now());
create table institutional_memberships (id uuid primary key default gen_random_uuid(), organization_id uuid not null references institutional_organizations(id), wallet_address text not null check (wallet_address = lower(wallet_address)), role text not null, status text not null default 'ACTIVE', created_at timestamptz not null default now(), revoked_at timestamptz, unique (organization_id, wallet_address));
create table auth_challenges (id uuid primary key default gen_random_uuid(), wallet_address text not null check (wallet_address = lower(wallet_address)), nonce_hash text not null unique, domain text not null, uri text not null, chain_id integer not null, statement text not null, issued_at timestamptz not null, expires_at timestamptz not null, consumed_at timestamptz);
create table auth_sessions (id uuid primary key default gen_random_uuid(), session_token_hash text not null unique, wallet_address text not null check (wallet_address = lower(wallet_address)), organization_id uuid not null references institutional_organizations(id), created_at timestamptz not null default now(), expires_at timestamptz not null, last_seen_at timestamptz not null default now(), revoked_at timestamptz);
alter table institutional_organizations enable row level security; alter table institutional_memberships enable row level security; alter table auth_challenges enable row level security; alter table auth_sessions enable row level security;
revoke all on institutional_organizations, institutional_memberships, auth_challenges, auth_sessions from anon, authenticated;
